    # Greedy constructive search for a difference-cover set B
    # We maintain 0 in B to ensure all distances are absolute.
    # We iteratively cover the smallest uncovered difference by adding a new element.
    import time
    from itertools import combinations

    MAX_ELEMENTS = 2000  # deduped count cap
    TIME_LIMIT = 0.95  # seconds, safe cushion under typical eval limits

    B = {0}
    start = time.time()

    def current_diffs(Bset):
        """Return all positive differences obtainable from B."""
        bs = sorted(Bset)
        diffs = set()
        for i in range(len(bs)):
            for j in range(i + 1, len(bs)):
                d = bs[j] - bs[i]
                if d > 0:
                    diffs.add(d)
        return diffs

    def compute_n(diffs):
        """Largest n such that 1..n are all contained in diffs."""
        n = 0
        while (n + 1) in diffs:
            n += 1
        return n

    # loop to grow B until time/memory limits hit
    while len(B) < MAX_ELEMENTS and (time.time() - start) < TIME_LIMIT:
        diffs = current_diffs(B)
        n = compute_n(diffs)

        # find smallest uncovered difference
        d = 1
        while d in diffs:
            d += 1
        # If there is no uncovered gap up to some large bound, stop
        if d <= 0:
            break

        # Generate candidate positions that would realize distance d with some b in B
        candidates = set()
        for b in B:
            cand1 = b + d  # ensures cand1 - b = d
            if cand1 >= 0:
                candidates.add(cand1)
            cand2 = max(B) - d  # cand2 could have |cand2 - b| = d for some b
            if cand2 >= 0:
                candidates.add(cand2)

        # Prefer candidate that adds many new diffs
        best_candidate = None
        best_gain = -1
        for x in candidates:
            if x in B:
                continue
            newB = sorted(B | {x})
            new_diffs = set()
            for i in range(len(newB)):
                for j in range(i + 1, len(newB)):
                    new_diffs.add(newB[j] - newB[i])
            gain = sum(1 for k in range(1, d + 1) if k not in diffs and k in new_diffs)
            if gain > best_gain:
                best_gain = gain
                best_candidate = x

        if best_candidate is None:
            # If no beneficial candidate found, try a simple fallback: add the next uncovered distance from 0
            cand = d
            if cand not in B:
                best_candidate = cand
            else:
                # as a last resort, add max(B) + d
                best_candidate = max(B) + d if (max(B) + d) not in B else None

        if best_candidate is None:
            break

        B.add(best_candidate)

        # Optional early stop: if we already achieved clean cover up to some n that's large, break
        # Here we rely on natural progression; time-limited.

    # Ensure 0 is present
    B.add(0)

    # Return a deduplicated, sorted list
    return sorted(B)

